using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using System.Linq;using System;
public static class DesktopMonitorStandAudit20261031{public static void Run(){var scene=EditorSceneManager.OpenScene(LibraryLoungeBuild.ScenePath,OpenSceneMode.Single);var cafe=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CafePrototype>(true)).Single();for(int i=0;i<2;i++){Transform s=cafe.screens[i].transform;var rr=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Single(x=>x.name=="Warm framed monitor "+(i+1));Debug.Log("DESKTOP_GEOMETRY seat="+i+" screen="+s.position+" size="+s.lossyScale+" forward="+s.forward+" bottom="+s.TransformPoint(new Vector3(0,-.5f,0))+" decorative="+rr.position);foreach(var part in rr.GetComponentsInChildren<Renderer>(true))Debug.Log("DESKTOP_GEOMETRY_PROP seat="+i+" name="+part.name+" bounds="+part.bounds+" enabled="+part.enabled);foreach(var part in s.GetComponentsInChildren<Renderer>(true))Debug.Log("DESKTOP_GEOMETRY_SCREEN seat="+i+" name="+part.name+" bounds="+part.bounds+" enabled="+part.enabled);}}}
